// Generated by the Haspataal MCP server (generate_typescript) from the backend contract.
// api(): the helper from get_guide("envelope-and-errors"). Types come from the declared request and response models.
import { api } from "../bridge";

export interface TariffOut {
  hospital_name: string;
  as_of: string;
  currency: string;
  categories: TariffCategoryOut[];
  wards: TariffWardOut[];
  lab_tests: TariffLabTestOut[];
}

export interface TariffCategoryOut {
  category: "OPD" | "IPD" | "OT" | "Imaging" | "RoomCharge" | "Procedure" | "Other";
  label: string;
  items: TariffItemOut[];
}

export interface TariffItemOut {
  service_id: number;
  code: string;
  name: string;
  category: "OPD" | "IPD" | "OT" | "Imaging" | "RoomCharge" | "Procedure" | "Other";
  price: number;
  department_name: string | null;
}

export interface TariffWardOut {
  ward_id: number;
  name: string;
  ward_type: "General" | "Private" | "SemiPrivate" | "ICU" | "CCU" | "NICU" | "Surgical" | "Pediatric" | "Maternity" | "Emergency" | "Isolation" | "Other";
  bed_day_price: number | null;
}

export interface TariffLabTestOut {
  test_id: number;
  code: string;
  name: string;
  section: string;
  price: number;
}

/** The tariff: every price, by category — GET /api/v1/tariff (who may call: any logged-in user). */
export function getTariff(): Promise<TariffOut> {
  return api<TariffOut>("GET", `/tariff`, undefined);
}

/** The tariff to print and display (PDF) — GET /api/v1/tariff/pdf (who may call: any logged-in user). */
export function tariffPdf(): Promise<unknown> {
  return api<unknown>("GET", `/tariff/pdf`, undefined);
}
